<template>
  <div class="redbag">
    <div v-if="!currentStatus" class="show" @click="getMons()" />
    <div v-if="currentStatus" class="open">
      <div class="text">
        {{ redbagMons }}
      </div>
    </div>
    <van-icon v-if="currentStatus" class="close-icon" name="cross" @click="currentStatus=false;$emit('close')" />
  </div>
</template>
<script>
import { getPackMons } from '@/api/user'
export default {
  props: {
    redbaghbid: {
      type: String,
      default: ''
    }
  },
  data() {
    return {
      currentStatus: false,
      redbagMons: ''
    }
  },
  methods: {
    async getMons() {
      const res = await getPackMons({ packid: this.redbaghbid })
      this.redbagMons = res.mons
      this.currentStatus = true
      this.$store.dispatch('user/getInfo')
    }
  }
}
</script>
